import sys, io
md, hist = sys.argv[1], sys.argv[2]   # CLAUDE.md, CLAUDE-history.md
s = io.open(md, encoding='utf-8').read()
def R(old, new):
    global s
    assert s.count(old) == 1, old[:80]
    s = s.replace(old, new)
R("| **Git** | Pushed up to CW (`93fc0e3`) on 2026-10-29. CX committed, waiting for her push. |",
  "| **Git** | Pushed up to CW (`93fc0e3`) on 2026-10-29. CX, and CY to DC together, committed, waiting for her push. |")
R("The 13 Beginner Lesson Books are rebuilt fun first: 'Guess first!', a challenge under every step, 'After this chapter, I can' with tick boxes (CU).",
  "The 13 Beginner Lesson Books are rebuilt fun first: 'Guess first!', a challenge under every step, 'After this chapter, I can' with tick boxes (CU); the 8 Prelim books (CZ) and the 8 Grade 1 books (DB) too. 'Make your own' opens inside the chapter, and a tool opened from a chapter goes back to it (CY).")
a = s.index("| **drills.html** (the Piano Butler drills, unlisted) |"); b = s.index(" |\n", a)
s = s[:b] + " The Prelim and Grade 1 checkpoints are on paper too: `?book=check&floor=1|2` and `?book=checkkey&floor=1|2`, on the Books shelf after chapters 21 and 29 (DA, DC)." + s[b:]
R("- Push: CV, the CLAUDE.md tidy and CW.", "- Push: CX, and CY to DC (one commit).")
R("- Nothing open on the board right now. The two-week freeze: her OK (2026-10-29) to no full stop, the Prelim books after the trial starts. The app code in its own file: built (CW).",
  "- Nothing open on the board right now. The Prelim books: she chose not to wait for the trial (2026-10-30 00:36); built (CZ).")
R("1. The Prelim floor's Lesson Books, fun first, once the trial has started. Then the Workbooks, and splitting the mixed Grades 2-3 rooms.",
  "1. The Grades 2 and 3 books, fun first (and splitting their mixed rooms), with their checkpoints on paper. Then the Workbooks.")
old = "reads `drills.src.html` and writes `drills.html` and `drills.app.js` (the hash in `?v=` is the code's). Uses"
if old in s:   # the stack-size note, written in CW's mirror but never sent to the Mac
    s = s.replace(old, "reads `drills.src.html` and writes `drills.html` and `drills.app.js` (the hash in `?v=` is the code's; in the desktop app's Linux shell run it as `node --stack-size=8000 tools/precompile.js`, or its parse check runs out of stack). Uses")
